// TextView — Gtk.TextView
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles textview with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { InputHints, InputPurpose, Justification, WrapMode } from "@/lib/enums"

export interface TextViewProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.TextView */
  acceptsTab?: boolean

  /** gint, from Gtk.TextView */
  bottomMargin?: number

  /** TextBuffer, from Gtk.TextView */
  buffer?: ReactNode

  /** gboolean, from Gtk.TextView */
  cursorVisible?: boolean

  /** gboolean, from Gtk.TextView */
  editable?: boolean

  /** Gio.MenuModel, from Gtk.TextView */
  extraMenu?: ReactNode

  /** utf8, from Gtk.TextView */
  imModule?: string

  /** gint, from Gtk.TextView */
  indent?: number

  /** InputHints, from Gtk.TextView */
  inputHints?: InputHints[]

  /** InputPurpose, from Gtk.TextView */
  inputPurpose?: InputPurpose

  /** Justification, from Gtk.TextView */
  justification?: Justification

  /** gint, from Gtk.TextView */
  leftMargin?: number

  /** gboolean, from Gtk.TextView */
  monospace?: boolean

  /** gboolean, from Gtk.TextView */
  overwrite?: boolean

  /** gint, from Gtk.TextView */
  pixelsAboveLines?: number

  /** gint, from Gtk.TextView */
  pixelsBelowLines?: number

  /** gint, from Gtk.TextView */
  pixelsInsideWrap?: number

  /** gint, from Gtk.TextView */
  rightMargin?: number

  /** Pango.TabArray, from Gtk.TextView */
  tabs?: ReactNode

  /** gint, from Gtk.TextView */
  topMargin?: number

  /** WrapMode, from Gtk.TextView */
  wrapMode?: WrapMode
}

export function TextView({ className, children }: TextViewProps) {
  return (
    <div className={cn("caret-[var(--accent-bg-color)]", className)}>
      {children}
    </div>
  )
}
